/**
 * Site admin metabox behaviour (agency/social custom fields + hours day chips).
 */
(function ($) {
	'use strict';
	function renumber(container, itemClass, namePrefix) {
		$(container).children('.' + itemClass).each(function (index) {
			$(this).find('input').each(function () {
				var name = $(this).attr('name') || '';
				name = name.replace(new RegExp(namePrefix + '\\[\\d+\\]'), namePrefix + '[' + index + ']');
				$(this).attr('name', name);
			});
		});
	}
	function initCustomFields(opts) {
		var $container = $(opts.container);
		var template = $(opts.template).html() || '';
		if (!$container.length || !template) return;
		$(document).on('click', opts.addBtn, function (e) {
			e.preventDefault();
			var index = $container.children('.' + opts.itemClass).length;
			$container.append(template.replace(/\{\{index\}\}/g, String(index)));
		});
		$(document).on('click', opts.removeClass, function (e) {
			e.preventDefault();
			$(this).closest('.' + opts.itemClass).remove();
			renumber(opts.container, opts.itemClass, opts.namePrefix);
		});
	}
	$(function () {
		initCustomFields({
			container: '#tourism-core-agency-custom-container',
			template: '#tourism-core-agency-custom-template',
			itemClass: 'tourism-core-agency-custom-item',
			addBtn: '#tourism-core-agency-add',
			removeClass: '.tourism-core-agency-remove',
			namePrefix: 'tourism_agency_custom'
		});
		initCustomFields({
			container: '#tourism-core-social-custom-container',
			template: '#tourism-core-social-custom-template',
			itemClass: 'tourism-core-social-custom-item',
			addBtn: '#tourism-core-social-add',
			removeClass: '.tourism-core-social-remove',
			namePrefix: 'tourism_social_custom'
		});
		var $items = $('.tourism-core-hours-day-item');
		if ($items.length) {
			function repaint() {
				$items.each(function () {
					var $item = $(this);
					var checked = $item.find('input[type="checkbox"]').is(':checked');
					$item.css({ borderColor: checked ? '#f38a38' : '#d0d4d9', background: checked ? '#fff7ef' : '#fff' });
					$item.find('span').css({ color: checked ? '#f38a38' : '#606a73' });
				});
			}
			$(document).on('change', '.tourism-core-hours-day-item input[type="checkbox"]', repaint);
			repaint();
		}
	});
})(jQuery);
